INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat eine Subnetzmaske immer 32 Bits?', 2, '[{"text": "Ja", "correct": true, "because": "IPv4-Standard"}, {"text": "Nein", "correct": false, "because": "Keine Abweichung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat die Subnetzmaske?', 3, '[{"text": "Trennt Netzwerk- und Hostanteil", "correct": true, "because": "Definiert Grenze"}, {"text": "Erhöht die Adresszahl", "correct": false, "because": "Begrenzt Hosts"}, {"text": "Ändert die Adresse", "correct": false, "because": "Nur Interpretation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Maske hat 32 Bits. b) Sie ist immer 255.255.255.0.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maske variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Subnetzmaske?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Struktur"}, {"text": "Netzwerktrennung", "correct": false, "because": "Hauptfunktion"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255.255.255.255 eine gültige Maske ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kein Hostanteil"}, {"text": "Ja", "correct": false, "because": "Technisch möglich, aber unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske trennt bei 192.168.1.0 die ersten 24 Bits?', 3, '[{"text": "255.255.255.0", "correct": true, "because": "24 Bits Netzwerk"}, {"text": "255.255.0.0", "correct": false, "because": "Nur 16 Bits"}, {"text": "255.0.0.0", "correct": false, "because": "Nur 8 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Subnetzmaske?', 5, '[{"text": "32 Bits", "correct": true, "because": "IPv4-Länge"}, {"text": "Trennt Anteile", "correct": true, "because": "Netzwerk vs. Host"}, {"text": "Ändert Adressen", "correct": false, "because": "Nur Interpretation"}, {"text": "128 Bits", "correct": false, "because": "IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Maske definiert das Netzwerk. b) Sie ist immer fix. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maske kann variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Subnetzmaske?', 4, '[{"text": "Bitstruktur", "correct": false, "because": "Definiert Aufbau"}, {"text": "Trennungslogik", "correct": false, "because": "Kernfunktion"}, {"text": "Grafische Darstellung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 255.255.0.0 eine Standardmaske?', 2, '[{"text": "Ja", "correct": true, "because": "Für Klasse B üblich"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske erlaubt die meisten Hosts?', 4, '[{"text": "255.0.0.0", "correct": true, "because": "24 Bits für Hosts"}, {"text": "255.255.255.0", "correct": false, "because": "Nur 8 Bits"}, {"text": "255.255.255.252", "correct": false, "because": "Nur 2 Hosts"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Maske die Adresse verschlüsselt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Trennung, keine Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Maskenwahl?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Hostanzahl"}, {"text": "Schnelligkeit", "correct": false, "because": "Nicht primär"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 32 Bits sind Standard. b) Die Maske kann 0.0.0.0 sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "0.0.0.0 ist unpraktisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen hat die Subnetzmaske?', 5, '[{"text": "Netzwerktrennung", "correct": true, "because": "Definiert Grenze"}, {"text": "Hostbegrenzung", "correct": true, "because": "Bestimmt Anzahl"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht ihre Aufgabe"}, {"text": "Protokollwechsel", "correct": false, "because": "IPv4-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Maske unwichtig?', 3, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Struktur"}, {"text": "Trennungslogik", "correct": false, "because": "Kernfunktion"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Maske den Hostanteil auf 0 Bits setzen?', 3, '[{"text": "Ja", "correct": true, "because": "255.255.255.255 ist möglich"}, {"text": "Nein", "correct": false, "because": "Technisch machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255.255.255.248 für kleine Netze passt?', 2, '[{"text": "Ja", "correct": true, "because": "6 Hosts möglich"}, {"text": "Nein", "correct": false, "because": "Geeignet für klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske nutze ich für ein Netz mit 2 Geräten?', 4, '[{"text": "255.255.255.252", "correct": true, "because": "2 Hosts, 30 Bits"}, {"text": "255.255.255.0", "correct": false, "because": "Zu viele Hosts"}, {"text": "255.0.0.0", "correct": false, "because": "Viel zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft hat 255.255.255.0?', 3, '[{"text": "24 Netzwerkbits", "correct": true, "because": "8 Hostbits übrig"}, {"text": "32 Hostbits", "correct": false, "because": "Nur 8 Bits frei"}, {"text": "16 Netzwerkbits", "correct": false, "because": "Klasse B"}]');
